    if Result.to_int first < 0 then check first;
    let requested = !@ count in
    if requested = 0 then [] else
    let storage = CArray.of_list (PhysicalDeviceToolProperties.t) (List.init requested (fun _ -> PhysicalDeviceToolProperties.make ())) in
    let result = Vk_fn.get_physical_device_tool_properties_ext (arg_physical_device) (count) (CArray.start storage) in
    if Result.equal result Result.incomplete then fetch () else begin
      check result;
      CArray.to_list (CArray.from_ptr (CArray.start storage) (!@ count))
